// See README.md for license details.
// -----------------------------------------------------------------------------
//  NpuAssembler.scala — Scala-side assembler for NPU instruction words
//
//  Produces 32-bit UInt literals that can be poked directly into
//  NeuralCoreMicroOp.word in simulation.
//
//  Usage example (in a spec):
//    import isa.NpuAssembler._
//    val instr = vadd(rd=0, rs1=1, rs2=2, width=VX)
//    dut.io.micro_op.word.poke(instr)
//
//  All methods return a Scala Int (bit pattern) that can be converted to
//  UInt via .U in a Chisel context, or wrapped by the asUInt helper.
// -----------------------------------------------------------------------------

package isa

import chisel3._

object NpuAssembler {

  // ---- Constants -----------------------------------------------------------

  // Width selectors (funct7[1:0])
  val VX = 0  // N(bits)-wide lanes
  val VE = 1  // 2N-wide lanes
  val VR = 2  // 4N-wide lanes

  // Rounding modes (funct7[3:2])
  val RNE   = 0
  val RTZ   = 1
  val FLOOR = 2
  val CEIL  = 3

  // Dtype class (funct7[6:5])
  val INT = 0
  val FP  = 1
  val BF  = 2

  // Format codes for vcvt (funct3 = dst, funct7[2:0] = src)
  val S8   = 0
  val S16  = 1
  val S32  = 2
  val F32  = 3
  val BF16 = 4
  val BF8  = 5   // BF8 variant (E4M3 vs E5M2) from bf8E5M2 parameter

  // ---- Encoding helpers ----------------------------------------------------

  /** Encode funct7 for R-type vector ops. */
  def f7(width: Int = VX, round: Int = RNE, sat: Boolean = false, dtype: Int = INT): Int =
    (width & 3) | ((round & 3) << 2) | ((if (sat) 1 else 0) << 4) | ((dtype & 3) << 5)

  /** Encode funct7 for VALU_CVT. */
  def f7Cvt(srcFmt: Int, sat: Boolean = true, round: Int = RNE, bf8E5M2: Boolean = false): Int =
    (srcFmt & 7) | ((if (sat) 1 else 0) << 3) | ((round & 3) << 4) | ((if (bf8E5M2) 1 else 0) << 6)

  /** Build R-type instruction word (returns Long to avoid signed-int overflow at bit 31). */
  def encR(opcode: Int, funct3: Int, funct7: Int, rd: Int, rs1: Int, rs2: Int): Int = {
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            ((rs2.toLong & 0x1F) << 20) |
            ((funct7.toLong & 0x7F) << 25)
    (w & 0xFFFFFFFFL).toInt  // keep 32 bits, return as (possibly signed) Int
  }

  /** Build I-type instruction word (imm is sign-extended 12-bit). */
  def encI(opcode: Int, funct3: Int, rd: Int, rs1: Int, imm: Int): Int = {
    val imm12 = imm.toLong & 0xFFF
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            (imm12 << 20)
    (w & 0xFFFFFFFFL).toInt
  }

  /** Build S-type (FMA) instruction word. rs3 at [31:27], rnd at [26:25]. */
  def encS(opcode: Int, funct3: Int, rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int = {
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            ((rs2.toLong & 0x1F) << 20) |
            ((round.toLong & 0x3) << 25) |
            ((rs3.toLong & 0x1F) << 27)
    (w & 0xFFFFFFFFL).toInt
  }

  // ---- NOP / special -------------------------------------------------------

  val nop: Int = 0x00  // opcode=0x00, everything zero

  // ---- VALU_ARITH (opcode=0x10) --------------------------------------------

  def vadd (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 0, f7(width, sat=sat), rd, rs1, rs2)
  def vsub (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 1, f7(width, sat=sat), rd, rs1, rs2)
  def vmul (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 2, f7(width, sat=sat), rd, rs1, rs2)
  def vneg (rd: Int, rs1: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 3, f7(width, sat=sat), rd, rs1, 0)
  def vabs (rd: Int, rs1: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 4, f7(width, sat=sat), rd, rs1, 0)
  def vmax (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int =
    encR(0x10, 5, f7(width), rd, rs1, rs2)
  def vmin (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int =
    encR(0x10, 6, f7(width), rd, rs1, rs2)
  def vrsub(rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 7, f7(width, sat=sat), rd, rs1, rs2)

  // ---- VALU_LOGIC (opcode=0x11) --------------------------------------------

  def vsll(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 0, f7(width), rd, rs1, rs2)
  def vsrl(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 1, f7(width), rd, rs1, rs2)
  def vsra(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 2, f7(width), rd, rs1, rs2)
  def vrol(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 3, f7(width), rd, rs1, rs2)
  def vxor(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 4, f7(width), rd, rs1, rs2)
  def vnot(rd: Int, rs1: Int, width: Int = VX): Int            = encR(0x11, 5, f7(width), rd, rs1, 0)
  def vor (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int  = encR(0x11, 6, f7(width), rd, rs1, rs2)
  def vand(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int  = encR(0x11, 7, f7(width), rd, rs1, rs2)

  // ---- VALU_REDUCE (opcode=0x12) -------------------------------------------

  def vsum (rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 0, f7(width), rd, rs1, 0)
  def vrmax(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 1, f7(width), rd, rs1, 0)
  def vrmin(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 2, f7(width), rd, rs1, 0)
  def vrand(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 3, f7(width), rd, rs1, 0)
  def vror (rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 4, f7(width), rd, rs1, 0)
  def vrxor(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 5, f7(width), rd, rs1, 0)

  // ---- VALU_LUT (opcode=0x13) — programmable two-bank LUT -------------------
  // Bank select: 0=A (default), 1=B.

  /**
   * Per-lane lookup: out[i] = lut_bank[in_a_vx[i]].
   * bank=0 → bank A (funct3=0), bank=1 → bank B (funct3=1).
   */
  def vlut(rd: Int, rs1: Int, bank: Int = 0): Int =
    encR(0x13, bank & 1, f7(VX), rd, rs1, 0)

  /**
   * Write one K×4-byte segment from VR[rs1] into the selected LUT bank.
   * segment: which K×4-entry block (0-based) within the 256-entry table.
   * bank=0 → bank A (funct3=4), bank=1 → bank B (funct3=5).
   * I-type: rd=0 (no register-file destination); imm=segment.
   */
  def vsetlut(rs1: Int, segment: Int, bank: Int = 0): Int =
    encI(0x13, 4 + (bank & 1), 0, rs1, segment)

  // ---- VALU_CVT (opcode=0x14) ----------------------------------------------
  // funct3 = dst fmt code; f7 encodes src + sat + round + bf8 variant

  def vcvt(rd: Int, rs1: Int,
           dstFmt: Int, srcFmt: Int,
           sat: Boolean = true, round: Int = RNE,
           bf8E5M2: Boolean = false): Int =
    encR(0x14, dstFmt, f7Cvt(srcFmt, sat, round, bf8E5M2), rd, rs1, 0)

  // Convenience aliases
  def vcvt_s8_s32 (rd: Int, rs1: Int, sat: Boolean = true,  round: Int = RNE): Int = vcvt(rd, rs1, S8,   S32, sat, round)
  def vcvt_s32_s8 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, S32, S8)
  def vcvt_s32_f32(rd: Int, rs1: Int, round: Int = RNE): Int = vcvt(rd, rs1, S32, F32, round=round)
  def vcvt_f32_s32(rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, S32, sat=false)
  def vcvt_f32_s8 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, S8,  sat=false)
  def vcvt_s8_f32 (rd: Int, rs1: Int, sat: Boolean = true, round: Int = RNE): Int = vcvt(rd, rs1, S8,   F32, sat, round)
  def vcvt_f32_bf16(rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, BF16, sat=false)
  def vcvt_bf16_f32(rd: Int, rs1: Int): Int = vcvt(rd, rs1, BF16, F32, sat=false)
  def vcvt_f32_bf8 (rd: Int, rs1: Int, e5m2: Boolean = false): Int = vcvt(rd, rs1, F32, BF8, sat=false, bf8E5M2=e5m2)
  def vcvt_bf8_f32 (rd: Int, rs1: Int, e5m2: Boolean = false): Int = vcvt(rd, rs1, BF8, F32, sat=false, bf8E5M2=e5m2)
  def vcvt_s16_s32 (rd: Int, rs1: Int, sat: Boolean = true): Int   = vcvt(rd, rs1, S16, S32, sat)
  def vcvt_s32_s16 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, S32, S16, sat=false)

  // ---- VALU_BCAST (opcode=0x15) --------------------------------------------

  /** Broadcast lane 0 of rs1 to all K lanes of rd (R-format). */
  def vbcast(rd: Int, rs1: Int, width: Int = VX): Int =
    encR(0x15, 0, f7(width), rd, rs1, 0)

  /** Broadcast sign-extended 12-bit immediate to all K lanes of rd (I-format). */
  def vbcastImm(rd: Int, imm: Int, width: Int = VX): Int =
    encI(0x15, 1, rd, 0, imm)

  // ---- VALU_FP (opcode=0x16) — FP32 on VR ---------------------------------

  def vfadd(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 0, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfsub(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 1, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfmul(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 2, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfneg(rd: Int, rs1: Int): Int =
    encR(0x16, 3, f7(VR, dtype=FP), rd, rs1, 0)
  def vfabs(rd: Int, rs1: Int): Int =
    encR(0x16, 4, f7(VR, dtype=FP), rd, rs1, 0)
  def vfmax(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x16, 5, f7(VR, dtype=FP), rd, rs1, rs2)
  def vfmin(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x16, 6, f7(VR, dtype=FP), rd, rs1, rs2)

  // ---- VALU_FP_FMA (opcode=0x17) — S-format -------------------------------

  def vfma (rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 0, rd, rs1, rs2, rs3, round)
  def vfms (rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 1, rd, rs1, rs2, rs3, round)
  def vnfma(rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 2, rd, rs1, rs2, rs3, round)
  def vnfms(rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 3, rd, rs1, rs2, rs3, round)

  // ---- VALU_MOV (opcode=0x18) ----------------------------------------------

  def vmov (rd: Int, rs1: Int, width: Int = VX): Int =
    encR(0x18, 0, f7(width), rd, rs1, 0)
  def vmovi(rd: Int, imm: Int, width: Int = VX): Int =
    encI(0x18, 1, rd, 0, imm)
  def vmovh(rd: Int, imm: Int): Int =
    encI(0x18, 2, rd, 0, imm)

  // ---- MMA (opcode=0x03) ---------------------------------------------------

  /** mma rd=outVR, rs1=A_VX_base, rs2=B_VX_base; keep in funct7[4] (sat bit). */
  def mma(rd: Int, rs1: Int, rs2: Int, keep: Boolean = true): Int =
    encR(0x03, 0, f7(VR, sat=keep), rd, rs1, rs2)
  def mmaLast(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x03, 1, f7(VR), rd, rs1, rs2)
  def mmaReset(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x03, 2, f7(VR), rd, rs1, rs2)

  // ---- LD / ST (opcodes 0x01 / 0x02) --------------------------------------

  def ldVx(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 3, rd, base, offset)
  def ldVe(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 4, rd, base, offset)
  def ldVr(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 5, rd, base, offset)
  def stVx(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 3, 0, base, offset)
  def stVe(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 4, 0, base, offset)
  def stVr(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 5, 0, base, offset)

  // ---- Convenience: convert Scala Int to Chisel UInt -----------------------
  implicit class IntToUInt(val v: Int) {
    // Convert to UInt treating the int as an unsigned 32-bit bit pattern
    def asUInt: chisel3.UInt = (v.toLong & 0xFFFFFFFFL).U(32.W)
  }
}

// See README.md for license details.
// -----------------------------------------------------------------------------
//  instrFormat.scala — RISC-V-inspired 32-bit instruction word layout
//
//  Parameters used throughout the ISA:
//    N(bits) — base lane width (default 8).  Always spelled N(bits) in prose.
//    L       — number of base VX registers (default 32, divisible by 4).
//    K       — SIMD lane count per register (default 8 for tests, 64 at top).
//              Equals MMALU's array-side parameter n at the backend boundary.
//
//  Instruction formats (32-bit word):
//
//  R-type  [funct7(7) | rs2(5) | rs1(5) | funct3(3) | rd(5) | opcode(7)]
//  I-type  [    imm[11:0](12)  | rs1(5) | funct3(3) | rd(5) | opcode(7)]
//  S-type  [rs3(5)|rnd(2)| rs2(5) | rs1(5) | funct3(3) | rd(5) | opcode(7)]
//
//  funct7 attribute layout (R-type):
//    [1:0] width  : 00=VX (N bits)  01=VE (2N bits)  10=VR (4N bits)  11=reserved
//    [3:2] round  : 00=RNE  01=RTZ  10=floor  11=ceil
//    [4]   sat    : 0=wrap  1=saturate
//    [6:5] dtype  : 00=INT  01=FP   10=BF     11=reserved
//
//  vcvt (VALU_CVT family) uses funct7 differently:
//    [2:0] src format code  (see FmtCode enum)
//    [3]   saturate
//    [5:4] round mode
//    [6]   BF8 variant      0=E4M3  1=E5M2
//
//  funct3 meanings are family-specific; see instSetArch.scala.
//  rd, rs1, rs2 index VX[0..L-1].  VE uses rd[3:0]; VR uses rd[2:0].
// -----------------------------------------------------------------------------

package isa

import chisel3._
import chisel3.util._

// ---------------------------------------------------------------------------
// Bit-position constants (field boundaries in the 32-bit word)
// ---------------------------------------------------------------------------
object InstrBits {
  val OPCODE_LO  =  0;  val OPCODE_HI  =  6   // 7 bits
  val RD_LO      =  7;  val RD_HI      = 11   // 5 bits
  val FUNCT3_LO  = 12;  val FUNCT3_HI  = 14   // 3 bits
  val RS1_LO     = 15;  val RS1_HI     = 19   // 5 bits
  val RS2_LO     = 20;  val RS2_HI     = 24   // 5 bits
  val FUNCT7_LO  = 25;  val FUNCT7_HI  = 31   // 7 bits

  // I-type immediate: bits[31:20]
  val IMM_I_LO   = 20;  val IMM_I_HI   = 31   // 12 bits (sign-extended)

  // S-type (FMA): rs3 at [31:27], round at [26:25]
  val RS3_LO     = 27;  val RS3_HI     = 31   // 5 bits
  val RND_S_LO   = 25;  val RND_S_HI   = 26   // 2 bits

  // funct7 attribute sub-fields
  val F7_WIDTH_LO = 0;  val F7_WIDTH_HI = 1   // [1:0] in funct7
  val F7_ROUND_LO = 2;  val F7_ROUND_HI = 3   // [3:2] in funct7
  val F7_SAT      = 4                          // [4]   in funct7
  val F7_DTYPE_LO = 5;  val F7_DTYPE_HI = 6   // [6:5] in funct7

  // vcvt funct7 sub-fields
  val F7_CVT_SRC_LO = 0; val F7_CVT_SRC_HI = 2  // [2:0]
  val F7_CVT_SAT    = 3                           // [3]
  val F7_CVT_RND_LO = 4; val F7_CVT_RND_HI = 5  // [5:4]
  val F7_CVT_BF8    = 6                           // [6] BF8 variant
}

// ---------------------------------------------------------------------------
// Width class: which register class the instruction operates on
// ---------------------------------------------------------------------------
object VecWidth extends ChiselEnum {
  val VX = Value(0.U(2.W))   // N(bits)-wide lanes
  val VE = Value(1.U(2.W))   // 2N-wide lanes
  val VR = Value(2.U(2.W))   // 4N-wide lanes
  val VW_RSV = Value(3.U(2.W)) // reserved
}

// ---------------------------------------------------------------------------
// Rounding mode
// ---------------------------------------------------------------------------
object VecRound extends ChiselEnum {
  val RNE   = Value(0.U(2.W))  // round to nearest, ties to even (IEEE default)
  val RTZ   = Value(1.U(2.W))  // round toward zero (truncate)
  val FLOOR = Value(2.U(2.W))  // round toward −∞
  val CEIL  = Value(3.U(2.W))  // round toward +∞
}

// ---------------------------------------------------------------------------
// Dtype class (high-level family; see FmtCode for precise per-op format)
// ---------------------------------------------------------------------------
object VecDtypeCls extends ChiselEnum {
  val INT = Value(0.U(2.W))
  val FP  = Value(1.U(2.W))
  val BF  = Value(2.U(2.W))
  val DC_RSV = Value(3.U(2.W)) // reserved
}

// ---------------------------------------------------------------------------
// Format codes used by vcvt (3-bit src and dst selectors)
// ---------------------------------------------------------------------------
object FmtCode {
  val S8   = 0.U(3.W)
  val S16  = 1.U(3.W)
  val S32  = 2.U(3.W)
  val F32  = 3.U(3.W)
  val BF16 = 4.U(3.W)
  val BF8  = 5.U(3.W)   // variant (E4M3/E5M2) comes from funct7[6]
  val RSV6 = 6.U(3.W)
  val RSV7 = 7.U(3.W)
}

// ---------------------------------------------------------------------------
// Scala-level decoded representation of the funct7 attribute field.
// Used in tests and in the assembler; not a Chisel bundle.
// ---------------------------------------------------------------------------
case class Funct7Attrs(
  width:  Int = 0,   // VecWidth value
  round:  Int = 0,   // VecRound value
  sat:    Boolean = false,
  dtype:  Int = 0,   // VecDtypeCls value
) {
  def encode: Int =
    (width & 3) | ((round & 3) << 2) | ((if (sat) 1 else 0) << 4) | ((dtype & 3) << 5)
}

case class CvtFunct7(
  srcFmt: Int = 0,
  sat:    Boolean = true,
  round:  Int = 0,
  bf8E5M2: Boolean = false,
) {
  def encode: Int =
    (srcFmt & 7) | ((if (sat) 1 else 0) << 3) | ((round & 3) << 4) | ((if (bf8E5M2) 1 else 0) << 6)
}

// See README.md for license details.
// -----------------------------------------------------------------------------
//  instSetArch.scala — NPU opcode families and per-family funct3 enums
//
//  Encoding model: RISC-V-inspired 32-bit instruction word.
//    opcode (7b) selects a functional *family*.
//    funct3 (3b) selects the sub-operation within the family.
//    funct7 (7b) carries attributes: width, round, saturate, dtype class.
//    rd, rs1, rs2 (5b each) index the register file.
//
//  See instrFormat.scala for bit-position constants and attribute enums.
//  See NpuAssembler.scala for a Scala-side assembler that builds instruction words.
//
//  Notation :
//    N(bits) — base lane width in bits (default 8). MMALU's nbits.
//    L       — number of VX base registers (default 32, must be div-by-4).
//    K       — SIMD lane count per register (8 for tests, 64 at top).
//              Equals MMALU's array-side n at the backend boundary.
//    VX[0..L-1]   — L  registers of K × N    bits
//    VE[0..L/2-1] — 16 registers of K × 2N   bits (alias VX[2i..2i+1])
//    VR[0..L/4-1] — 8  registers of K × 4N   bits (alias VX[4i..4i+3])
// -----------------------------------------------------------------------------

package isa

import chisel3._
import chisel3.util._

// ---------------------------------------------------------------------------
// Opcode families (7-bit primary decode field)
// ---------------------------------------------------------------------------
object OpFamily extends ChiselEnum {
  val NOP          = Value(0x00.U(7.W))
  val LD           = Value(0x01.U(7.W))
  val ST           = Value(0x02.U(7.W))
  val MMA          = Value(0x03.U(7.W))
  val VALU_ARITH   = Value(0x10.U(7.W))
  val VALU_LOGIC   = Value(0x11.U(7.W))
  val VALU_REDUCE  = Value(0x12.U(7.W))
  val VALU_LUT     = Value(0x13.U(7.W))
  val VALU_CVT     = Value(0x14.U(7.W))
  val VALU_BCAST   = Value(0x15.U(7.W))
  val VALU_FP      = Value(0x16.U(7.W))
  val VALU_FP_FMA  = Value(0x17.U(7.W))
  val VALU_MOV     = Value(0x18.U(7.W))
}

// ---------------------------------------------------------------------------
// funct3 encodings per family
// ---------------------------------------------------------------------------

// VALU_ARITH (opcode=0x10): elementwise arithmetic on VX/VE/VR
// Width from funct7[1:0]; saturate from funct7[4].
// RISC-V aligned where possible.
object Funct3Arith {
  val ADD  = 0.U(3.W)   // rd = rs1 + rs2
  val SUB  = 1.U(3.W)   // rd = rs1 - rs2
  val MUL  = 2.U(3.W)   // rd = rs1 * rs2  (narrow sat; wide on out_wide)
  val NEG  = 3.U(3.W)   // rd = -rs1  (rs2 ignored)
  val ABS  = 4.U(3.W)   // rd = |rs1|  (rs2 ignored)
  val MAX  = 5.U(3.W)   // rd = max(rs1, rs2)
  val MIN  = 6.U(3.W)   // rd = min(rs1, rs2)
  val RSUB = 7.U(3.W)   // rd = rs2 - rs1  (reverse subtract)
}

// VALU_LOGIC (opcode=0x11): bitwise and shift operations on VX/VE/VR
// RISC-V aligned: SLL=001, SRL/SRA=101, XOR=100, OR=110, AND=111.
object Funct3Logic {
  val SLL = 0.U(3.W)   // logical left shift
  val SRL = 1.U(3.W)   // logical right shift
  val SRA = 2.U(3.W)   // arithmetic right shift (sign extending)
  val ROL = 3.U(3.W)   // rotate left
  val XOR = 4.U(3.W)   // RV xor (100)
  val NOT = 5.U(3.W)   // bitwise NOT (rs2 ignored)
  val OR  = 6.U(3.W)   // RV or (110)
  val AND = 7.U(3.W)   // RV and (111)
}

// VALU_REDUCE (opcode=0x12): horizontal reductions, result broadcast to all lanes
object Funct3Reduce {
  val SUM  = 0.U(3.W)  // Σ lanes → out_wide broadcast
  val RMAX = 1.U(3.W)  // max over lanes → broadcast
  val RMIN = 2.U(3.W)  // min over lanes → broadcast
  val RAND = 3.U(3.W)  // AND over lanes → broadcast
  val ROR  = 4.U(3.W)  // OR  over lanes → broadcast
  val RXOR = 5.U(3.W)  // XOR over lanes → broadcast
  // 6, 7 reserved
}

// VALU_LUT (opcode=0x13): programmable two-bank LUT, raw byte-in/byte-out
//
//  vlut   (funct3=0/1) — per-lane 256-entry lookup from bank A (funct3=0)
//                        or bank B (funct3=1).  R-type; rd=VX dst, rs1=VX src.
//                        round[0] in the decoded bundle = bank select (0=A, 1=B).
//
//  vsetlut (funct3=4/5) — write one K×4-byte segment of the LUT bank from a
//                          VR source register.  I-type; rs1=VR src, imm=segment.
//                          funct3=4 → bank A, funct3=5 → bank B.
//                          No register-file write (side-effect on VALU-internal state only).
//
//  Segment packing: VR[rs1] holds K lanes × 4 bytes = K×4 consecutive LUT
//  entries.  Segment index s maps to LUT entries [s×K×4 .. (s+1)×K×4 − 1].
//  At K=8  : 8 vsetlut calls fill the full 256-byte bank.
//  At K=64 : 1 vsetlut call fills the full 256-byte bank.
//
//  The Qfmt object (vec.scala) remains available as a Scala-only compiler and
//  test utility for generating table data; it is no longer synthesised as hardware.
object Funct3Lut {
  val VLUT_A    = 0.U(3.W)  // per-lane lookup from bank A (R-type)
  val VLUT_B    = 1.U(3.W)  // per-lane lookup from bank B (R-type)
  // 2..3 reserved
  val VSETLUT_A = 4.U(3.W)  // write K×4-byte segment into bank A (I-type)
  val VSETLUT_B = 5.U(3.W)  // write K×4-byte segment into bank B (I-type)
  // 6..7 reserved
}

// VALU_CVT (opcode=0x14): type conversions
// funct3 = destination format code (FmtCode object in instrFormat.scala)
// funct7[2:0] = source format code; funct7[3]=sat; funct7[5:4]=round; funct7[6]=BF8 variant
// Width is determined by src/dst format (e.g. s32 implies VR; s8 implies VX).

// VALU_BCAST (opcode=0x15): scalar broadcast to all K lanes
object Funct3Bcast {
  val REG = 0.U(3.W)   // R-format: rd[i] = rs1[0] for all i; width from funct7[1:0]
  val IMM = 1.U(3.W)   // I-format: rd[i] = sext(imm[11:0]); width from funct7[1:0]
  // 2..7 reserved
}

// VALU_FP (opcode=0x16): FP32 arithmetic on VR lanes; width and dtype implicit (VR, FP)
// funct7[3:2] carries round mode; funct7[6:5] reserved-must-be-01 (FP dtype).
object Funct3Fp {
  val FADD = 0.U(3.W)
  val FSUB = 1.U(3.W)
  val FMUL = 2.U(3.W)
  val FNEG = 3.U(3.W)  // rs2 ignored
  val FABS = 4.U(3.W)  // rs2 ignored
  val FMAX = 5.U(3.W)
  val FMIN = 6.U(3.W)
  // 7 reserved
}

// VALU_FP_FMA (opcode=0x17): fused multiply-add, S-format (rd, rs1, rs2, rs3)
// rd = rs1 * rs2 + rs3  (FMA), etc.
object Funct3Fma {
  val FMA  = 0.U(3.W)   // rd =  (rs1 * rs2) + rs3
  val FMS  = 1.U(3.W)   // rd =  (rs1 * rs2) - rs3
  val NFMA = 2.U(3.W)   // rd = -(rs1 * rs2) + rs3
  val NFMS = 3.U(3.W)   // rd = -(rs1 * rs2) - rs3
  // 4..7 reserved
}

// VALU_MOV (opcode=0x18): register move and immediate load
object Funct3Mov {
  val MOV  = 0.U(3.W)  // R-format: rd = rs1 (copy), width from funct7[1:0]
  val MOVI = 1.U(3.W)  // I-format: rd[0] = sext(imm); other lanes unchanged
  val MOVH = 2.U(3.W)  // I-format: rd[0][31:16] = imm[15:0]; low 16 unchanged
  // 3..7 reserved
}

// MMA (opcode=0x03): systolic array matrix multiply-accumulate
object Funct3Mma {
  val MMA       = 0.U(3.W)   // normal accumulate (keep from funct7[4])
  val MMA_LAST  = 1.U(3.W)   // assert clct signal; finalize result
  val MMA_RESET = 2.U(3.W)   // clear accumulator
  // 3..7 reserved
}

// LD / ST (opcodes 0x01/0x02): memory access; funct3 encodes transfer width
object Funct3Mem {
  val BYTE  = 0.U(3.W)  // N-bit lane (byte)
  val HALF  = 1.U(3.W)  // 2N-bit
  val WORD  = 2.U(3.W)  // 4N-bit
  val VX_VEC = 3.U(3.W) // full K-lane VX vector
  val VE_VEC = 4.U(3.W) // full K-lane VE vector
  val VR_VEC = 5.U(3.W) // full K-lane VR vector
  // 6..7 reserved
}

// ---------------------------------------------------------------------------
// Backwards-compatible NeuralCoreMicroOp: wraps the raw 32-bit instruction
// word.  The InstrDecoder module unpacks it into DecodedMicroOp.
// ---------------------------------------------------------------------------
class NeuralCoreMicroOp extends Bundle {
  val word = UInt(32.W)
}

// See README.md for license details.
// Tests for InstrDecoder: encode 32-bit words with NpuAssembler, verify decoded fields.

package isa

import chisel3._
import chisel3.simulator.EphemeralSimulator._
import org.scalatest.flatspec.AnyFlatSpec
import isa.micro_op._

class InstrDecoderSpec extends AnyFlatSpec {
  import NpuAssembler._

  // Width constants (0=VX, 1=VE, 2=VR) — matches VecWidth enum values
  val WX = 0; val WE = 1; val WR = 2

  def check(dut: InstrDecoder, instr: Int,
            expFamily: OpFamily.Type,
            expOp: VecOp.Type,
            expWidth: Int = WX,   // use WX/WE/WR constants above
            expSat: Boolean = false,
            expRound: Int = RNE,
            expRd: Int = 0, expRs1: Int = 0, expRs2: Int = 0,
            expectIllegal: Boolean = false): Unit = {
    dut.io.instr.poke((instr.toLong & 0xFFFFFFFFL).U)
    dut.clock.step(0)  // combinational
    if (expectIllegal) {
      assert(dut.io.illegal.peek().litToBoolean, s"Expected illegal for 0x${instr.toHexString}")
    } else {
      assert(!dut.io.illegal.peek().litToBoolean, s"Unexpected illegal for 0x${instr.toHexString}")
      // Check all UInt decoded fields
      dut.io.decoded.valu.regCls.expect(expWidth.U)
      dut.io.decoded.valu.saturate.expect(expSat.B)
      dut.io.decoded.valu.round.expect(expRound.U)
      dut.io.decoded.rd.expect(expRd.U)
      dut.io.decoded.rs1.expect(expRs1.U)
      dut.io.decoded.rs2.expect(expRs2.U)
      // ChiselEnum fields (family, op, dtype) are verified indirectly:
      // correct VecOp decode is tested by the VALU functional specs which poke
      // the ctrl bundle via the same decoder and verify outputs.
    }
  }

  "InstrDecoder" should "decode vadd VX" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vadd(rd=1, rs1=2, rs2=3, width=VX),
            OpFamily.VALU_ARITH, VecOp.vadd,
            expWidth=WX, expRd=1, expRs1=2, expRs2=3)
    }
  }

  "InstrDecoder" should "decode vadd VE saturate" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vadd(rd=4, rs1=5, rs2=6, width=VE, sat=true),
            OpFamily.VALU_ARITH, VecOp.vadd,
            expWidth=WE, expSat=true, expRd=4, expRs1=5, expRs2=6)
    }
  }

  "InstrDecoder" should "decode vadd VR" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vadd(rd=0, rs1=0, rs2=1, width=VR),
            OpFamily.VALU_ARITH, VecOp.vadd, expWidth=WR, expRs2=1)
    }
  }

  "InstrDecoder" should "decode vsub" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vsub(rd=1, rs1=2, rs2=3),
            OpFamily.VALU_ARITH, VecOp.vsub, expRd=1, expRs1=2, expRs2=3)
    }
  }

  "InstrDecoder" should "decode vmul" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vmul(rd=1, rs1=2, rs2=3),
            OpFamily.VALU_ARITH, VecOp.vmul, expRd=1, expRs1=2, expRs2=3)
    }
  }

  "InstrDecoder" should "decode vneg/vabs" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vneg(rd=0, rs1=1), OpFamily.VALU_ARITH, VecOp.vneg, expRs1=1)
      check(dut, vabs(rd=0, rs1=1), OpFamily.VALU_ARITH, VecOp.vabs, expRs1=1)
    }
  }

  "InstrDecoder" should "decode vand/vor/vxor/vnot" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vand(rd=1, rs1=2, rs2=3), OpFamily.VALU_LOGIC, VecOp.vand, expRd=1, expRs1=2, expRs2=3)
      check(dut, vor (rd=1, rs1=2, rs2=3), OpFamily.VALU_LOGIC, VecOp.vor,  expRd=1, expRs1=2, expRs2=3)
      check(dut, vxor(rd=1, rs1=2, rs2=3), OpFamily.VALU_LOGIC, VecOp.vxor, expRd=1, expRs1=2, expRs2=3)
      check(dut, vnot(rd=1, rs1=2),         OpFamily.VALU_LOGIC, VecOp.vnot, expRd=1, expRs1=2)
    }
  }

  "InstrDecoder" should "decode vsll/vsrl/vsra" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vsll(rd=0, rs1=1, rs2=2), OpFamily.VALU_LOGIC, VecOp.vsll, expRs1=1, expRs2=2)
      check(dut, vsrl(rd=0, rs1=1, rs2=2), OpFamily.VALU_LOGIC, VecOp.vsrl, expRs1=1, expRs2=2)
      check(dut, vsra(rd=0, rs1=1, rs2=2), OpFamily.VALU_LOGIC, VecOp.vsra, expRs1=1, expRs2=2)
    }
  }

  "InstrDecoder" should "decode vsum/vrmax on VX" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vsum(rd=0, rs1=1),  OpFamily.VALU_REDUCE, VecOp.vsum,  expRs1=1)
      check(dut, vrmax(rd=0, rs1=1), OpFamily.VALU_REDUCE, VecOp.vrmax, expRs1=1)
    }
  }

  "InstrDecoder" should "decode vlut (bank A and bank B)" in {
    simulate(new InstrDecoder) { dut =>
      // vlut bank A: funct3=0, round[0]=0
      check(dut, vlut(rd=2, rs1=1, bank=0), OpFamily.VALU_LUT, VecOp.vlut,
            expWidth=WX, expRd=2, expRs1=1)
      dut.io.decoded.valu.round.expect(0.U)  // bank A → round[0]=0

      // vlut bank B: funct3=1, round[0]=1
      check(dut, vlut(rd=2, rs1=1, bank=1), OpFamily.VALU_LUT, VecOp.vlut,
            expWidth=WX, expRound=1, expRd=2, expRs1=1)
      dut.io.decoded.valu.round.expect(1.U)  // bank B → round[0]=1
    }
  }

  "InstrDecoder" should "decode vsetlut (bank A and bank B)" in {
    simulate(new InstrDecoder) { dut =>
      // vsetlut bank A: funct3=4, I-type, imm=segment, width=VR
      dut.io.instr.poke((vsetlut(rs1=3, segment=2, bank=0).toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      assert(!dut.io.illegal.peek().litToBoolean, "vsetlut bank A must not be illegal")
      dut.io.decoded.valu.round.expect(0.U)          // bank A
      dut.io.decoded.valu.imm.expect(2.S)            // segment=2
      dut.io.decoded.rs1.expect(3.U)                 // rs1=3

      // vsetlut bank B: funct3=5
      dut.io.instr.poke((vsetlut(rs1=5, segment=7, bank=1).toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      assert(!dut.io.illegal.peek().litToBoolean, "vsetlut bank B must not be illegal")
      dut.io.decoded.valu.round.expect(1.U)          // bank B
      dut.io.decoded.valu.imm.expect(7.S)            // segment=7
      dut.io.decoded.rs1.expect(5.U)                 // rs1=5
    }
  }

  "InstrDecoder" should "flag reserved VALU_LUT funct3 values as illegal" in {
    simulate(new InstrDecoder) { dut =>
      // funct3=2 and funct3=3 are reserved
      for (f3 <- Seq(2, 3, 6, 7)) {
        val instr = encR(0x13, f3, f7(VX), 0, 1, 0)
        dut.io.instr.poke((instr.toLong & 0xFFFFFFFFL).U)
        dut.clock.step(0)
        assert(dut.io.illegal.peek().litToBoolean,
          s"VALU_LUT funct3=$f3 should be illegal")
      }
    }
  }

  "InstrDecoder" should "decode vbcast reg and imm" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vbcast(rd=2, rs1=0, width=VR),
            OpFamily.VALU_BCAST, VecOp.vbcast_reg, expWidth=WR, expRd=2)
      // I-format: bits[24:20] carry imm[9:5]. imm=42=0b101010, so imm[4:0]=10.
      check(dut, vbcastImm(rd=3, imm=42, width=VX),
            OpFamily.VALU_BCAST, VecOp.vbcast_imm, expWidth=WX, expRd=3, expRs2=10)
    }
  }

  "InstrDecoder" should "decode FP32 arith ops" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vfadd(rd=0, rs1=1, rs2=2), OpFamily.VALU_FP, VecOp.vfadd, expWidth=WR, expRs1=1, expRs2=2)
      check(dut, vfsub(rd=0, rs1=1, rs2=2), OpFamily.VALU_FP, VecOp.vfsub, expWidth=WR, expRs1=1, expRs2=2)
      check(dut, vfmul(rd=0, rs1=1, rs2=2), OpFamily.VALU_FP, VecOp.vfmul, expWidth=WR, expRs1=1, expRs2=2)
      check(dut, vfneg(rd=0, rs1=1),         OpFamily.VALU_FP, VecOp.vfneg, expWidth=WR, expRs1=1)
      check(dut, vfabs(rd=0, rs1=1),         OpFamily.VALU_FP, VecOp.vfabs, expWidth=WR, expRs1=1)
    }
  }

  "InstrDecoder" should "decode vfma (S-format)" in {
    simulate(new InstrDecoder) { dut =>
      dut.io.instr.poke((vfma(rd=0, rs1=1, rs2=2, rs3=3).toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      assert(!dut.io.illegal.peek().litToBoolean)
      // family/op verified indirectly; check rs3_idx decoding
      // (family/op ChiselEnum peek not directly accessible in Chisel 6 EphemeralSimulator)
      dut.io.decoded.valu.rs3_idx.expect(3.U)
    }
  }

  "InstrDecoder" should "decode vcvt s32->f32" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vcvt_f32_s32(rd=1, rs1=0),
            OpFamily.VALU_CVT, VecOp.vcvt_f32_s32, expWidth=WR, expRd=1)
    }
  }

  "InstrDecoder" should "decode vcvt f32->s8 with saturation" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vcvt_s8_f32(rd=31, rs1=0, sat=true),
            OpFamily.VALU_CVT, VecOp.vcvt_s8_f32, expWidth=WR, expSat=true, expRd=31)
    }
  }

  "InstrDecoder" should "decode vcvt bf16 conversions" in {
    simulate(new InstrDecoder) { dut =>
      check(dut, vcvt_f32_bf16(rd=0, rs1=1), OpFamily.VALU_CVT, VecOp.vcvt_f32_bf16, expWidth=WR, expRs1=1)
      check(dut, vcvt_bf16_f32(rd=0, rs1=1), OpFamily.VALU_CVT, VecOp.vcvt_bf16_f32, expWidth=WR, expRs1=1)
    }
  }

  "InstrDecoder" should "decode vcvt bf8 conversions (E4M3 and E5M2)" in {
    simulate(new InstrDecoder) { dut =>
      // E4M3 (default)
      dut.io.instr.poke((vcvt_bf8_f32(rd=0, rs1=1, e5m2=false).toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      assert(!dut.io.illegal.peek().litToBoolean)
      // dtype is a ChiselEnum; check that illegal is not set (dtype correctness
      // verified by VALUCvtSpec which exercises the BF8 conversion ops end-to-end)
      assert(!dut.io.illegal.peek().litToBoolean, "E4M3 vcvt should not be illegal")

      // E5M2
      dut.io.instr.poke((vcvt_bf8_f32(rd=0, rs1=1, e5m2=true).toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      assert(!dut.io.illegal.peek().litToBoolean, "E5M2 vcvt should not be illegal")
    }
  }

  "InstrDecoder" should "decode MMA instruction" in {
    simulate(new InstrDecoder) { dut =>
      dut.io.instr.poke((mma(rd=0, rs1=1, rs2=2, keep=true).toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      assert(!dut.io.illegal.peek().litToBoolean)
      // MMA family verified via mma_keep flag below
      dut.io.decoded.mma_keep.expect(true.B)
    }
  }

  "InstrDecoder" should "assert illegal for reserved opcode" in {
    simulate(new InstrDecoder) { dut =>
      // opcode 0x7F is not a valid family
      dut.io.instr.poke(0x7F.U)
      dut.clock.step(0)
      assert(dut.io.illegal.peek().litToBoolean, "Reserved opcode should be illegal")
    }
  }

  "InstrDecoder" should "assert illegal for vcvt same src==dst" in {
    simulate(new InstrDecoder) { dut =>
      // src=F32 (3), dst=F32 (3) — same format
      val illegalCvt = encR(0x14, 3, f7Cvt(srcFmt=3), 0, 0, 0)
      dut.io.instr.poke((illegalCvt.toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      assert(dut.io.illegal.peek().litToBoolean, "Same src==dst cvt should be illegal")
    }
  }

  "InstrDecoder" should "decode rounding mode" in {
    simulate(new InstrDecoder) { dut =>
      val instrRTZ = vcvt_s8_f32(rd=0, rs1=1, round=RTZ)
      dut.io.instr.poke((instrRTZ.toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      dut.io.decoded.valu.round.expect(RTZ.U)

      val instrFloor = vcvt_s8_f32(rd=0, rs1=1, round=FLOOR)
      dut.io.instr.poke((instrFloor.toLong & 0xFFFFFFFFL).U)
      dut.clock.step(0)
      dut.io.decoded.valu.round.expect(FLOOR.U)
    }
  }
}
